export interface CartLine {
  sku: string;
  qty: number;
  unitCents: number;
}

export const TAX_RATE = 0.2;

// Discount is a fraction, e.g. 0.1 for 10% off.
export function priceCart(lines: CartLine[], discount: number) {
  const subtotal = lines.reduce((sum, l) => sum + l.unitCents * l.qty, 0);
  const taxed = Math.round(subtotal * (1 + TAX_RATE));
  const total = Math.round(taxed * (1 - discount));
  return { subtotal, tax: taxed - subtotal, total };
}

