import type { CartLine } from "./pricing";

const STOCK: Record<string, number> = { a: 5, b: 2 };

export async function reserveStock(lines: CartLine[]): Promise<void> {
  for (const l of lines) {
    const have = STOCK[l.sku] ?? 0;
    if (have < l.qty) {
      throw new Error(`out_of_stock:${l.sku}`);
    }
    STOCK[l.sku] = have - l.qty;
  }
}

